window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_45", [
  {"q":"'यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन' के ऐतिहासिक संदर्भ में 'वैज्ञानिक व भौगोलिक क्रांति' निम्नलिखित में से क्या है?","options":["1871 की फ्रैंकफर्ट संधि से फ्रांस को अल्सास-लॉरेन जर्मनी को देना पड़ा, जो प्रथम विश्व युद्ध का दीर्घकालिक कारण बना","1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)"],"correct":2,"explanation":"इंग्लैंड में 1688 की 'गौरवशाली क्रांति' (Glorious / Bloodless Revolution) द्वारा बिना रक्तपात संसद की सर्वोच्चता व संवैधानिक राजतंत्र स्थापित हुआ ('बिल ऑफ राइट्स 1689')।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बोस्टन टी पार्टी (1773)   |   1. प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\nB. वर्साय की संधि (1919)   |   2. व्लादिमीर इलिच लेनिन\nC. द सोशल कॉन्ट्रैक्ट   |   3. सैमुअल एडम्स (अमेरिकी क्रांति)\nD. बोल्शेविक क्रांति (1917)   |   4. ज्याँ-जैक रूसो","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"correct":2,"explanation":"सही सुमेलन: बोस्टन टी पार्टी (1773) (सैमुअल एडम्स (अमेरिकी क्रांति)), वर्साय की संधि (1919) (प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना), द सोशल कॉन्ट्रैक्ट (ज्याँ-जैक रूसो), बोल्शेविक क्रांति (1917) (व्लादिमीर इलिच लेनिन)।"},
  {"q":"'दास कैपिटल' (Das Kapital) एवं 'कम्युनिस्ट मेनिफेस्टो' (1848) किसके प्रमुख विचार ग्रंथ हैं?","options":["मॉन्टेस्क्यू","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","ज्याँ-जैक रूसो","एडम स्मिथ"],"correct":1,"explanation":"कार्ल मार्क्स ने वैज्ञानिक समाजवाद व वर्ग-संघर्ष के सिद्धांत का प्रतिपादन किया। इसने 1917 की रूसी व 1949 की चीनी क्रांति को वैचारिक आधार दिया।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n2. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n3. दास कैपिटल (1867) : व्लादिमीर इलिच लेनिन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया।) युग्म 2 सही (ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं।) युग्म 3 गलत (सही: दास कैपिटल (1867) — कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो))।"},
  {"q":"यूरोपीय पुनर्जागरण का प्रारंभ इटली के किस समृद्ध व्यापारिक नगर से माना जाता है जहाँ दांते, पेट्रार्क व दा विंची सक्रिय थे?","options":["फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार"],"correct":2,"explanation":"14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला। फ्रांसेस्को पेट्रार्क को 'मानववाद का पिता' (Father of Humanism) कहा जाता है।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n3. लियोनार्दो दा विंची : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।) युग्म 2 सही (14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला।) युग्म 3 सही (इतालवी पुनर्जागरण काल के दा विंची चित्रकार, मूर्तिकार, अभियंता व शरीर विज्ञानी थे।)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n2. वेल्थ ऑफ नेशंस (1776) : ज्यूसेपे मैजिनी\n3. यंग इटली (1831) : मॉन्टेस्क्यू\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं।) युग्म 2 गलत (सही: वेल्थ ऑफ नेशंस (1776) — एडम स्मिथ)। युग्म 3 गलत (सही: यंग इटली (1831) — ज्यूसेपे मैजिनी)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n2. बोल्शेविक क्रांति (1917) : सैमुअल एडम्स (अमेरिकी क्रांति)\n3. बोस्टन टी पार्टी (1773) : एडम स्मिथ\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना।) युग्म 2 गलत (सही: बोल्शेविक क्रांति (1917) — व्लादिमीर इलिच लेनिन)। युग्म 3 गलत (सही: बोस्टन टी पार्टी (1773) — सैमुअल एडम्स (अमेरिकी क्रांति))।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. द स्पिरिट ऑफ द लॉज : मॉन्टेस्क्यू\n2. दास कैपिटल (1867) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. वर्साय की संधि (1919) : व्लादिमीर इलिच लेनिन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मॉन्टेस्क्यू ने विधायिका, कार्यपालिका व न्यायपालिका के शक्ति पृथक्करण का सिद्धांत प्रस्तुत किया।) युग्म 2 गलत (सही: दास कैपिटल (1867) — कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो))। युग्म 3 गलत (सही: वर्साय की संधि (1919) — प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो\n2. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n3. दास कैपिटल (1867) : एडम स्मिथ\n4. द स्पिरिट ऑफ द लॉज : मॉन्टेस्क्यू","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'दास कैपिटल (1867)' का सही संबंध 'कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)' से है (न कि 'एडम स्मिथ' से)। कार्ल मार्क्स ने वैज्ञानिक समाजवाद व वर्ग-संघर्ष के सिद्धांत का प्रतिपादन किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. यंग इटली (1831) : ज्याँ-जैक रूसो\n2. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n3. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n4. बोल्शेविक क्रांति (1917) : व्लादिमीर इलिच लेनिन","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'यंग इटली (1831)' का सही संबंध 'ज्यूसेपे मैजिनी' से है (न कि 'ज्याँ-जैक रूसो' से)। मैजिनी ने मार्से में 'यंग इटली' की स्थापना कर युवाओं में लोकतांत्रिक राष्ट्रवाद जगाया।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n2. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n3. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी।) युग्म 2 सही (निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की।) युग्म 3 सही (14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला।)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो\n3. वर्साय की संधि (1919) : मॉन्टेस्क्यू\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (कार्ल मार्क्स ने वैज्ञानिक समाजवाद व वर्ग-संघर्ष के सिद्धांत का प्रतिपादन किया।) युग्म 2 सही (रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया।) युग्म 3 गलत (सही: वर्साय की संधि (1919) — प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वर्साय की संधि (1919)   |   1. ज्याँ-जैक रूसो\nB. यंग इटली (1831)   |   2. सैमुअल एडम्स (अमेरिकी क्रांति)\nC. बोस्टन टी पार्टी (1773)   |   3. प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\nD. द सोशल कॉन्ट्रैक्ट   |   4. ज्यूसेपे मैजिनी","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: वर्साय की संधि (1919) (प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना), यंग इटली (1831) (ज्यूसेपे मैजिनी), बोस्टन टी पार्टी (1773) (सैमुअल एडम्स (अमेरिकी क्रांति)), द सोशल कॉन्ट्रैक्ट (ज्याँ-जैक रूसो)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. दास कैपिटल (1867) : व्लादिमीर इलिच लेनिन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं।) युग्म 2 सही (28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना।) युग्म 3 गलत (सही: दास कैपिटल (1867) — कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो))।"},
  {"q":"'औपनिवेशिक विउपनिवेशीकरण (Decolonization): अफ्रीका, एशिया व राष्ट्रमंडल' के ऐतिहासिक संदर्भ में 'भारत की भूमिका' निम्नलिखित में से क्या है?","options":["1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","भारत ने बांडुंग सम्मेलन (1955) व संयुक्त राष्ट्र में उपनिवेशवाद एवं रंगभेद के विरुद्ध अग्रणी भूमिका निभाई"],"correct":3,"explanation":"दक्षिण अफ्रीका में रंगभेद (Apartheid) शासन के विरुद्ध 27 वर्ष जेल में रहने वाले नेल्सन मंडेला 1994 में दक्षिण अफ्रीका के प्रथम अश्वेत राष्ट्रपति बने।"},
  {"q":"'प्रथम विश्व युद्ध (1914–1918), रूसी क्रांति (1917) व वर्साय संधि' के ऐतिहासिक संदर्भ में 'रूसी क्रांति (1917)' निम्नलिखित में से क्या है?","options":["गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)","1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","मार्च/फरवरी 1917 (जार निकोलस II का पतन); नवंबर/अक्टूबर 1917 बोल्शेविक क्रांति (व्लादिमीर लेनिन — 'शांति, भूमि व रोटी', 'अप्रैल थीसिस', NEP 1921 व USSR गठन 1922)"],"correct":3,"explanation":"अमेरिकी राष्ट्रपति वुडरो विल्सन के '14 सूत्री सिद्धांत' (1918) के आधार पर 1920 में जिनेवा मुख्यालय के साथ 'लीग ऑफ नेशंस' बना, पर स्वयं अमेरिका इसका सदस्य नहीं बना।"},
  {"q":"रूस में 1917 की बोल्शेविक (अक्टूबर) क्रांति का मुख्य नेतृत्व किसने किया था?","options":["मॉन्टेस्क्यू","व्लादिमीर इलिच लेनिन","ज्याँ-जैक रूसो","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)"],"correct":1,"explanation":"लेनिन ने अप्रैल थीसिस जारी कर केरेंस्की की अंतरिम सरकार का तख्तापलट कर सोवियत सत्ता बनाई। 1921 में उन्होंने 'नई आर्थिक नीति' (NEP) भी लागू की।"},
  {"q":"प्रथम विश्व युद्ध (1914–1918), रूसी क्रांति (1917) व वर्साय संधि — इसके संबंध में 'प्रमुख कारण व संधियाँ' कौन/क्या था?","options":["14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)","प्रथम विश्व युद्ध: तात्कालिक कारण 28 जून 1914 को साराजेवो (बोस्निया) में ऑस्ट्रिया के राजकुमार आर्कड्यूक फ्रांज फर्डिनेंड की हत्या; मित्र राष्ट्र (ब्रिटेन, फ्रांस, रूस, 1917 में USA, जापान) बनाम केंद्रीय शक्तियाँ (जर्मनी, ऑस्ट्रिया-हंगरी, ऑटोमन तुर्की); वर्साय संधि (1919 — जर्मनी पर युद्ध अपराध थोपना व भारी हर्जाना); राष्ट्र संघ (League of Nations, 1920)"],"correct":3,"explanation":"अमेरिकी राष्ट्रपति वुडरो विल्सन के '14 सूत्री सिद्धांत' (1918) के आधार पर 1920 में जिनेवा मुख्यालय के साथ 'लीग ऑफ नेशंस' बना, पर स्वयं अमेरिका इसका सदस्य नहीं बना।"},
  {"q":"इटली और जर्मनी का एकीकरण (मैजिनी, कैवूर, गैरीबाल्डी व बिस्मार्क) — इसके संबंध में 'प्रमुख निर्माता व युद्ध' कौन/क्या था?","options":["14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","इटली एकीकरण (1861/1870): ज्यूसेपे मैजिनी ('यंग इटली' 1831 — आत्मा), काउंट कैवूर (कूटनीति — दिमाग), गैरीबाल्डी ('लाल कुर्ती' — तलवार); जर्मनी एकीकरण (1871): प्रशा के चांसलर ओटो वॉन बिस्मार्क ('रक्त और लौह नीति' — तीन युद्ध: डेनमार्क 1864, ऑस्ट्रिया सेडोवा 1866 व फ्रांस सेडान 1870 — वर्साय के शीशमहल में केसर विलियम I राज्याभिषेक)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)"],"correct":2,"explanation":"इटली के एकीकरण में पीडमोंट-सार्डिनिया राज्य के राजा विक्टर इमैनुएल द्वितीय ने केंद्रीय भूमिका निभाई और 1870 में रोम के विलय के साथ एकीकरण पूरा हुआ।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मार्टिन लूथर (जर्मनी) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n2. बास्तील दुर्ग का पतन (14 जुलाई 1789) : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n4. ओटो वॉन बिस्मार्क : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी। (अन्य सही युग्म: मार्टिन लूथर (जर्मनी)→कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार, बास्तील दुर्ग का पतन (14 जुलाई 1789)→फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श), ओटो वॉन बिस्मार्क→प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871))।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. द स्पिरिट ऑफ द लॉज : ज्यूसेपे मैजिनी\n3. यंग इटली (1831) : सैमुअल एडम्स (अमेरिकी क्रांति)\n4. बोस्टन टी पार्टी (1773) : व्लादिमीर इलिच लेनिन","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: कार्ल मार्क्स ने वैज्ञानिक समाजवाद व वर्ग-संघर्ष के सिद्धांत का प्रतिपादन किया। (अन्य सही युग्म: द स्पिरिट ऑफ द लॉज→मॉन्टेस्क्यू, यंग इटली (1831)→ज्यूसेपे मैजिनी, बोस्टन टी पार्टी (1773)→सैमुअल एडम्स (अमेरिकी क्रांति))।"},
  {"q":"16 दिसंबर 1773 की प्रसिद्ध 'बोस्टन टी पार्टी' घटना का नेतृत्व किसने किया था?","options":["ज्याँ-जैक रूसो","सैमुअल एडम्स (अमेरिकी क्रांति)","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","मॉन्टेस्क्यू"],"correct":1,"explanation":"ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं। यह 'प्रतिनिधित्व के बिना कर नहीं' के विरोध की निर्णायक घटना थी।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वर्साय की संधि (1919) : सैमुअल एडम्स (अमेरिकी क्रांति)\n2. बोस्टन टी पार्टी (1773) : व्लादिमीर इलिच लेनिन\n3. बोल्शेविक क्रांति (1917) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: वर्साय की संधि (1919) — प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)। युग्म 2 गलत (सही: बोस्टन टी पार्टी (1773) — सैमुअल एडम्स (अमेरिकी क्रांति))। युग्म 3 गलत (सही: बोल्शेविक क्रांति (1917) — व्लादिमीर इलिच लेनिन)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n2. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n3. लियोनार्दो दा विंची : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की।) युग्म 2 सही (जर्मनी के पोलैंड ('ऑपरेशन व्हाइट') हमले के दो दिन बाद 3 सितंबर को ब्रिटेन और फ्रांस युद्ध में कूद पड़े।) युग्म 3 गलत (सही: लियोनार्दो दा विंची — मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वेल्थ ऑफ नेशंस (1776) : ज्याँ-जैक रूसो\n2. द सोशल कॉन्ट्रैक्ट : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. द स्पिरिट ऑफ द लॉज : मॉन्टेस्क्यू\n4. वर्साय की संधि (1919) : ज्यूसेपे मैजिनी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: मॉन्टेस्क्यू ने विधायिका, कार्यपालिका व न्यायपालिका के शक्ति पृथक्करण का सिद्धांत प्रस्तुत किया। (अन्य सही युग्म: वेल्थ ऑफ नेशंस (1776)→एडम स्मिथ, द सोशल कॉन्ट्रैक्ट→ज्याँ-जैक रूसो, वर्साय की संधि (1919)→प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बोल्शेविक क्रांति (1917) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. दास कैपिटल (1867) : एडम स्मिथ\n3. वेल्थ ऑफ नेशंस (1776) : सैमुअल एडम्स (अमेरिकी क्रांति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: बोल्शेविक क्रांति (1917) — व्लादिमीर इलिच लेनिन)। युग्म 2 गलत (सही: दास कैपिटल (1867) — कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो))। युग्म 3 गलत (सही: वेल्थ ऑफ नेशंस (1776) — एडम स्मिथ)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लियोनार्दो दा विंची : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n2. इटली का फ्लोरेंस नगर : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. मार्टिन लूथर (जर्मनी) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n4. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया। (अन्य सही युग्म: लियोनार्दो दा विंची→मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र, इटली का फ्लोरेंस नगर→यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र, मार्टिन लूथर (जर्मनी)→कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. इटली का फ्लोरेंस नगर : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n2. लियोनार्दो दा विंची : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n3. ओटो वॉन बिस्मार्क : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: इटली का फ्लोरेंस नगर — यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र)। युग्म 2 गलत (सही: लियोनार्दो दा विंची — मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)। युग्म 3 गलत (सही: ओटो वॉन बिस्मार्क — प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n2. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n3. मार्टिन लूथर (जर्मनी) : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n4. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'मार्टिन लूथर (जर्मनी)' का सही संबंध 'कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार' से है (न कि 'प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)' से)। मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n2. लियोनार्दो दा विंची : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n3. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की।) युग्म 2 गलत (सही: लियोनार्दो दा विंची — मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)। युग्म 3 गलत (सही: जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) — द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा))।"},
  {"q":"[CDS/PSC PYQ] आधुनिक विश्व इतिहास में 'तीन वर्गों की व्यवस्था' (First, Second and Third Estate — पादरी, कुलीन व जनसाधारण) एवं 'टेनिस कोर्ट की शपथ' (1789) किससे संबंधित है?","options":["फ्रांसीसी क्रांति (तीसरे वर्ग द्वारा राष्ट्रीय सभा घोषणा व संविधान निर्माण प्रतिज्ञा)","1688 की इंग्लैंड की गौरवपूर्ण क्रांति","1917 की रूसी अक्टूबर क्रांति","1776 का अमेरिकी स्वतंत्रता संग्राम"],"correct":0,"explanation":"जून 1789 में एस्टेट्स-जनरल में मतदान प्रणाली के विरोध में तीसरे एस्टेट ने स्वयं को 'नेशनल असेंबली' घोषित कर पास के इंडोर टेनिस कोर्ट में नया संविधान बनाने की शपथ ली।"},
  {"q":"ऐतिहासिक संदर्भ में 'औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)' (प्रमुख कारण व घटनाएँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["इटली और जर्मनी का एकीकरण (मैजिनी, कैवूर, गैरीबाल्डी व बिस्मार्क)","औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)","फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट","यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन"],"correct":1,"explanation":"सात वर्षीय युद्ध (1756-63) के बाद ब्रिटेन द्वारा उपनिवेशों पर लगाए गए स्टैम्प एक्ट (1765) व चाय कर के विरोध में ही अमेरिकी क्रांति ने गति पकड़ी।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. यंग इटली (1831)   |   1. सैमुअल एडम्स (अमेरिकी क्रांति)\nB. बोस्टन टी पार्टी (1773)   |   2. व्लादिमीर इलिच लेनिन\nC. द स्पिरिट ऑफ द लॉज   |   3. ज्यूसेपे मैजिनी\nD. बोल्शेविक क्रांति (1917)   |   4. मॉन्टेस्क्यू","options":["A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: यंग इटली (1831) (ज्यूसेपे मैजिनी), बोस्टन टी पार्टी (1773) (सैमुअल एडम्स (अमेरिकी क्रांति)), द स्पिरिट ऑफ द लॉज (मॉन्टेस्क्यू), बोल्शेविक क्रांति (1917) (व्लादिमीर इलिच लेनिन)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. वर्साय की संधि (1919) : व्लादिमीर इलिच लेनिन\n2. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n3. द स्पिरिट ऑफ द लॉज : मॉन्टेस्क्यू\n4. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'वर्साय की संधि (1919)' का सही संबंध 'प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना' से है (न कि 'व्लादिमीर इलिच लेनिन' से)। 28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मार्टिन लूथर (जर्मनी) : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n3. ओटो वॉन बिस्मार्क : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n4. लियोनार्दो दा विंची : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की। (अन्य सही युग्म: मार्टिन लूथर (जर्मनी)→कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार, ओटो वॉन बिस्मार्क→प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871), लियोनार्दो दा विंची→मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. बोल्शेविक क्रांति (1917) : व्लादिमीर इलिच लेनिन\n2. द स्पिरिट ऑफ द लॉज : ज्यूसेपे मैजिनी\n3. यंग इटली (1831) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n4. वर्साय की संधि (1919) : सैमुअल एडम्स (अमेरिकी क्रांति)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: लेनिन ने अप्रैल थीसिस जारी कर केरेंस्की की अंतरिम सरकार का तख्तापलट कर सोवियत सत्ता बनाई। (अन्य सही युग्म: द स्पिरिट ऑफ द लॉज→मॉन्टेस्क्यू, यंग इटली (1831)→ज्यूसेपे मैजिनी, वर्साय की संधि (1919)→प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)।"},
  {"q":"'औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)' के ऐतिहासिक संदर्भ में 'संवैधानिक महत्व' निम्नलिखित में से क्या है?","options":["1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","1871 की फ्रैंकफर्ट संधि से फ्रांस को अल्सास-लॉरेन जर्मनी को देना पड़ा, जो प्रथम विश्व युद्ध का दीर्घकालिक कारण बना","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)"],"correct":2,"explanation":"सात वर्षीय युद्ध (1756-63) के बाद ब्रिटेन द्वारा उपनिवेशों पर लगाए गए स्टैम्प एक्ट (1765) व चाय कर के विरोध में ही अमेरिकी क्रांति ने गति पकड़ी।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n2. बास्तील दुर्ग का पतन (14 जुलाई 1789) : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n3. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n4. लियोनार्दो दा विंची : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला। (अन्य सही युग्म: जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)→द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा), बास्तील दुर्ग का पतन (14 जुलाई 1789)→फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श), लियोनार्दो दा विंची→मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)।"},
  {"q":"'सामाजिक समझौता' (The Social Contract) पुस्तक के लेखक कौन-से प्रबोधनकालीन दार्शनिक थे?","options":["मॉन्टेस्क्यू","ज्याँ-जैक रूसो","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","एडम स्मिथ"],"correct":1,"explanation":"रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया। नेपोलियन ने कहा था कि यदि रूसो न होते तो फ्रांसीसी क्रांति भी न होती।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n2. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n3. लियोनार्दो दा विंची : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी।) युग्म 2 सही (1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी।) युग्म 3 गलत (सही: लियोनार्दो दा विंची — मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)   |   1. द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\nB. बास्तील दुर्ग का पतन (14 जुलाई 1789)   |   2. इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nC. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)   |   3. यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\nD. इटली का फ्लोरेंस नगर   |   4. फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) (इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण), बास्तील दुर्ग का पतन (14 जुलाई 1789) (फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)), जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) (द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)), इटली का फ्लोरेंस नगर (यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. ओटो वॉन बिस्मार्क   |   1. इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nB. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)   |   2. कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\nC. लियोनार्दो दा विंची   |   3. प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\nD. मार्टिन लूथर (जर्मनी)   |   4. मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: ओटो वॉन बिस्मार्क (प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)), गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) (इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण), लियोनार्दो दा विंची (मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र), मार्टिन लूथर (जर्मनी) (कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. ओटो वॉन बिस्मार्क : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n2. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n4. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'ओटो वॉन बिस्मार्क' का सही संबंध 'प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)' से है (न कि 'मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र' से)। चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n2. ओटो वॉन बिस्मार्क : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n3. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n4. इटली का फ्लोरेंस नगर : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी। (अन्य सही युग्म: ओटो वॉन बिस्मार्क→प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871), जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)→द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा), इटली का फ्लोरेंस नगर→यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. वेल्थ ऑफ नेशंस (1776) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n3. बोल्शेविक क्रांति (1917) : व्लादिमीर इलिच लेनिन\n4. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'वेल्थ ऑफ नेशंस (1776)' का सही संबंध 'एडम स्मिथ' से है (न कि 'कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)' से)। एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वेल्थ ऑफ नेशंस (1776) : ज्याँ-जैक रूसो\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. द सोशल कॉन्ट्रैक्ट : व्लादिमीर इलिच लेनिन\n4. बोल्शेविक क्रांति (1917) : ज्यूसेपे मैजिनी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: 28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना। (अन्य सही युग्म: वेल्थ ऑफ नेशंस (1776)→एडम स्मिथ, द सोशल कॉन्ट्रैक्ट→ज्याँ-जैक रूसो, बोल्शेविक क्रांति (1917)→व्लादिमीर इलिच लेनिन)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लियोनार्दो दा विंची : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n2. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n3. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n4. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'लियोनार्दो दा विंची' का सही संबंध 'मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र' से है (न कि 'कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार' से)। इतालवी पुनर्जागरण काल के दा विंची चित्रकार, मूर्तिकार, अभियंता व शरीर विज्ञानी थे।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n2. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n3. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n4. लियोनार्दो दा विंची : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)' का सही संबंध 'द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)' से है (न कि 'प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)' से)। जर्मनी के पोलैंड ('ऑपरेशन व्हाइट') हमले के दो दिन बाद 3 सितंबर को ब्रिटेन और फ्रांस युद्ध में कूद पड़े।"},
  {"q":"14 जुलाई 1789 को 'बास्तील के किले का पतन' किस क्रांति का प्रतीकात्मक आरंभ था?","options":["यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार"],"correct":2,"explanation":"निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की। फ्रांस हर वर्ष 14 जुलाई को अपना राष्ट्रीय दिवस (Bastille Day) मनाता है।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. बोल्शेविक क्रांति (1917) : ज्यूसेपे मैजिनी\n4. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'बोल्शेविक क्रांति (1917)' का सही संबंध 'व्लादिमीर इलिच लेनिन' से है (न कि 'ज्यूसेपे मैजिनी' से)। लेनिन ने अप्रैल थीसिस जारी कर केरेंस्की की अंतरिम सरकार का तख्तापलट कर सोवियत सत्ता बनाई।"},
  {"q":"यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन — इसके संबंध में 'प्रमुख व्यक्तित्व व सिद्धांत' कौन/क्या था?","options":["इटली एकीकरण (1861/1870): ज्यूसेपे मैजिनी ('यंग इटली' 1831 — आत्मा), काउंट कैवूर (कूटनीति — दिमाग), गैरीबाल्डी ('लाल कुर्ती' — तलवार); जर्मनी एकीकरण (1871): प्रशा के चांसलर ओटो वॉन बिस्मार्क ('रक्त और लौह नीति' — तीन युद्ध: डेनमार्क 1864, ऑस्ट्रिया सेडोवा 1866 व फ्रांस सेडान 1870 — वर्साय के शीशमहल में केसर विलियम I राज्याभिषेक)","14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)"],"correct":3,"explanation":"इंग्लैंड में 1688 की 'गौरवशाली क्रांति' (Glorious / Bloodless Revolution) द्वारा बिना रक्तपात संसद की सर्वोच्चता व संवैधानिक राजतंत्र स्थापित हुआ ('बिल ऑफ राइट्स 1689')।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. बास्तील दुर्ग का पतन (14 जुलाई 1789) : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n2. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n4. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'बास्तील दुर्ग का पतन (14 जुलाई 1789)' का सही संबंध 'फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)' से है (न कि 'यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र' से)। निरंकुश राजतंत्र के प्रतीक पेरिस स्थित बास्तील जेल को जनता ने ध्वस्त कर फ्रांसीसी क्रांति शुरू की।"},
  {"q":"'स्पिरिट ऑफ द लॉज' (The Spirit of Laws — शक्ति पृथक्करण सिद्धांत) पुस्तक किस फ्रांसीसी विचारक ने लिखी?","options":["एडम स्मिथ","मॉन्टेस्क्यू","ज्याँ-जैक रूसो","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)"],"correct":1,"explanation":"मॉन्टेस्क्यू ने विधायिका, कार्यपालिका व न्यायपालिका के शक्ति पृथक्करण का सिद्धांत प्रस्तुत किया। अमेरिकी व भारतीय संविधान में शक्ति-संतुलन अवधारणा इससे गहराई से प्रभावित है।"},
  {"q":"[PSC/CDS PYQ] प्रथम विश्व युद्ध के बाद अमेरिकी राष्ट्रपति वुडरो विल्सन के 'चौदह सूत्री सिद्धांत' (14 Points) के परिणामस्वरूप 1920 में किस अंतर्राष्ट्रीय संस्था की स्थापना हुई?","options":["वारसॉ पैक्ट (Warsaw Pact)","उत्तरी अटलांटिक संधि संगठन (NATO)","संयुक्त राष्ट्र संघ (UNO, 1945)","राष्ट्र संघ (League of Nations — मुख्यालय: जिनेवा)"],"correct":3,"explanation":"यद्यपि वुडरो विल्सन राष्ट्र संघ के मुख्य प्रेरणास्रोत थे, परंतु अमेरिकी सीनेट ने वर्साय संधि की पुष्टि न करने के कारण अमेरिका स्वयं कभी राष्ट्र संघ का सदस्य नहीं बन सका।"},
  {"q":"'मोनालिसा' और 'द लास्ट सपर' विश्वप्रसिद्ध चित्रकलाओं के रचयिता बहुमुखी पुनर्जागरण कलाकार कौन थे?","options":["फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार"],"correct":1,"explanation":"इतालवी पुनर्जागरण काल के दा विंची चित्रकार, मूर्तिकार, अभियंता व शरीर विज्ञानी थे। माइकलएंजेलो ने 'डेविड' की मूर्ति और सिस्टीन चैपल की छत ('द लास्ट जजमेंट') चित्रित की।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. वर्साय की संधि (1919) : सैमुअल एडम्स (अमेरिकी क्रांति)\n2. बोस्टन टी पार्टी (1773) : मॉन्टेस्क्यू\n3. द स्पिरिट ऑफ द लॉज : व्लादिमीर इलिच लेनिन\n4. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया। (अन्य सही युग्म: वर्साय की संधि (1919)→प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना, बोस्टन टी पार्टी (1773)→सैमुअल एडम्स (अमेरिकी क्रांति), द स्पिरिट ऑफ द लॉज→मॉन्टेस्क्यू)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. द स्पिरिट ऑफ द लॉज : व्लादिमीर इलिच लेनिन\n4. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'द स्पिरिट ऑफ द लॉज' का सही संबंध 'मॉन्टेस्क्यू' से है (न कि 'व्लादिमीर इलिच लेनिन' से)। मॉन्टेस्क्यू ने विधायिका, कार्यपालिका व न्यायपालिका के शक्ति पृथक्करण का सिद्धांत प्रस्तुत किया।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n2. लियोनार्दो दा विंची : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n3. मार्टिन लूथर (जर्मनी) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला।) युग्म 2 सही (इतालवी पुनर्जागरण काल के दा विंची चित्रकार, मूर्तिकार, अभियंता व शरीर विज्ञानी थे।) युग्म 3 गलत (सही: मार्टिन लूथर (जर्मनी) — कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वेल्थ ऑफ नेशंस (1776)   |   1. ज्याँ-जैक रूसो\nB. वर्साय की संधि (1919)   |   2. एडम स्मिथ\nC. द सोशल कॉन्ट्रैक्ट   |   3. ज्यूसेपे मैजिनी\nD. यंग इटली (1831)   |   4. प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"correct":2,"explanation":"सही सुमेलन: वेल्थ ऑफ नेशंस (1776) (एडम स्मिथ), वर्साय की संधि (1919) (प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना), द सोशल कॉन्ट्रैक्ट (ज्याँ-जैक रूसो), यंग इटली (1831) (ज्यूसेपे मैजिनी)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. मार्टिन लूथर (जर्मनी) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।) युग्म 2 गलत (सही: मार्टिन लूथर (जर्मनी) — कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार)। युग्म 3 गलत (सही: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) — इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. द स्पिरिट ऑफ द लॉज : व्लादिमीर इलिच लेनिन\n2. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n3. बोल्शेविक क्रांति (1917) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n4. वर्साय की संधि (1919) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया। (अन्य सही युग्म: द स्पिरिट ऑफ द लॉज→मॉन्टेस्क्यू, बोल्शेविक क्रांति (1917)→व्लादिमीर इलिच लेनिन, वर्साय की संधि (1919)→प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वर्साय की संधि (1919) : सैमुअल एडम्स (अमेरिकी क्रांति)\n2. बोस्टन टी पार्टी (1773) : एडम स्मिथ\n3. वेल्थ ऑफ नेशंस (1776) : ज्याँ-जैक रूसो\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: वर्साय की संधि (1919) — प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना)। युग्म 2 गलत (सही: बोस्टन टी पार्टी (1773) — सैमुअल एडम्स (अमेरिकी क्रांति))। युग्म 3 गलत (सही: वेल्थ ऑफ नेशंस (1776) — एडम स्मिथ)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बोल्शेविक क्रांति (1917) : व्लादिमीर इलिच लेनिन\n2. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो\n3. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लेनिन ने अप्रैल थीसिस जारी कर केरेंस्की की अंतरिम सरकार का तख्तापलट कर सोवियत सत्ता बनाई।) युग्म 2 सही (रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया।) युग्म 3 सही (ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं।)।"},
  {"q":"ऐतिहासिक संदर्भ में '1929 की महामंदी; मुसोलिनी (इटली फासीवाद 'ब्लैक शर्ट्स'); हिटलर (जर्मनी नाजीवाद, 'मीन कैम्फ', तुष्टीकरण की नीति व 1938 म्यूनिख समझौता); WWII आरंभ: 1 सितंबर 1939 जर्मनी का पोलैंड आक्रमण; पर्ल हार्बर (दिसंबर 1941); स्टालिनग्राद; डी-डे नॉरमैंडी (1944); हिरोशिमा-नागासाकी (6 व 9 अगस्त 1945); संयुक्त राष्ट्र संघ UNO (24 अक्टूबर 1945)' (युद्ध, कारण व परिणाम) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन","औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)","फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट","फासीवाद-नाजीवाद, द्वितीय विश्व युद्ध (1939–1945) व UNO स्थापना"],"correct":3,"explanation":"शीत युद्ध के दौरान तृतीय विश्व के नव-स्वतंत्र देशों को सैन्य गुटों से दूर रखने हेतु 1961 में बेलग्रेड में प्रथम गुटनिरपेक्ष शिखर सम्मेलन (NAM) आयोजित हुआ।"},
  {"q":"इटली के एकीकरण में 'यंग इटली' (1831) संगठन किस देशभक्त विचारक ने बनाया था?","options":["ज्यूसेपे मैजिनी","ज्याँ-जैक रूसो","मॉन्टेस्क्यू","कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)"],"correct":0,"explanation":"मैजिनी ने मार्से में 'यंग इटली' की स्थापना कर युवाओं में लोकतांत्रिक राष्ट्रवाद जगाया। लाला लाजपत राय व सावरकर भी मैजिनी के जीवन से अत्यंत प्रेरित थे।"},
  {"q":"ऐतिहासिक संदर्भ में '1947 भारत-पाक, 1948 श्रीलंका-बर्मा, 1949 इंडोनेशिया (सुकर्णो), 1954 डिएन बिएन फू (वियतनाम — हो ची मिन्ह, जेनेवा समझौता), 1956 स्वेज संकट (नासिर), 1957 घाना (क्वामे नक्रूमा — उप-सहारा अफ्रीका में प्रथम स्वतंत्र), 1960 'अफ्रीका का वर्ष' (17 देश स्वतंत्र), 1994 दक्षिण अफ्रीका (नेल्सन मंडेला द्वारा रंगभेद समाप्ति)' (प्रमुख ऐतिहासिक प्रक्रिया) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट","औपनिवेशिक विउपनिवेशीकरण (Decolonization): अफ्रीका, एशिया व राष्ट्रमंडल","औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)","यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन"],"correct":1,"explanation":"दक्षिण अफ्रीका में रंगभेद (Apartheid) शासन के विरुद्ध 27 वर्ष जेल में रहने वाले नेल्सन मंडेला 1994 में दक्षिण अफ्रीका के प्रथम अश्वेत राष्ट्रपति बने।"},
  {"q":"1517 ई. में जर्मनी के विटेनबर्ग चर्च पर '95 थीसिस' (95 प्रश्न) चिपकाकर प्रोटेस्टेंट 'धर्मसुधार आंदोलन' किसने शुरू किया?","options":["फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र"],"correct":2,"explanation":"मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी। जबकि जेनेवा (स्विट्जरलैंड) में जॉन कैल्विन ने कैल्विनवाद का नेतृत्व किया।"},
  {"q":"फासीवाद-नाजीवाद, द्वितीय विश्व युद्ध (1939–1945) व UNO स्थापना — इसके संबंध में 'युद्ध, कारण व परिणाम' कौन/क्या था?","options":["14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","1929 की महामंदी; मुसोलिनी (इटली फासीवाद 'ब्लैक शर्ट्स'); हिटलर (जर्मनी नाजीवाद, 'मीन कैम्फ', तुष्टीकरण की नीति व 1938 म्यूनिख समझौता); WWII आरंभ: 1 सितंबर 1939 जर्मनी का पोलैंड आक्रमण; पर्ल हार्बर (दिसंबर 1941); स्टालिनग्राद; डी-डे नॉरमैंडी (1944); हिरोशिमा-नागासाकी (6 व 9 अगस्त 1945); संयुक्त राष्ट्र संघ UNO (24 अक्टूबर 1945)"],"correct":3,"explanation":"शीत युद्ध के दौरान तृतीय विश्व के नव-स्वतंत्र देशों को सैन्य गुटों से दूर रखने हेतु 1961 में बेलग्रेड में प्रथम गुटनिरपेक्ष शिखर सम्मेलन (NAM) आयोजित हुआ।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. बास्तील दुर्ग का पतन (14 जुलाई 1789) : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n3. इटली का फ्लोरेंस नगर : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n4. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'इटली का फ्लोरेंस नगर' का सही संबंध 'यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र' से है (न कि 'इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण' से)। 14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला।"},
  {"q":"'फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट' के ऐतिहासिक संदर्भ में 'नेपोलियन युग' निम्नलिखित में से क्या है?","options":["1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)","1871 की फ्रैंकफर्ट संधि से फ्रांस को अल्सास-लॉरेन जर्मनी को देना पड़ा, जो प्रथम विश्व युद्ध का दीर्घकालिक कारण बना"],"correct":0,"explanation":"फ्रांसीसी क्रांति के पश्चात 26 अगस्त 1789 को 'मनुष्य एवं नागरिक के अधिकारों की घोषणा' की गई, जिसका प्रभाव भारतीय संविधान की प्रस्तावना व टिपू सुल्तान तक दिखा।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n2. लियोनार्दो दा विंची : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\n3. बास्तील दुर्ग का पतन (14 जुलाई 1789) : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n4. ओटो वॉन बिस्मार्क : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: जर्मनी के पोलैंड ('ऑपरेशन व्हाइट') हमले के दो दिन बाद 3 सितंबर को ब्रिटेन और फ्रांस युद्ध में कूद पड़े। (अन्य सही युग्म: लियोनार्दो दा विंची→मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र, बास्तील दुर्ग का पतन (14 जुलाई 1789)→फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श), ओटो वॉन बिस्मार्क→प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. द स्पिरिट ऑफ द लॉज   |   1. ज्याँ-जैक रूसो\nB. वेल्थ ऑफ नेशंस (1776)   |   2. मॉन्टेस्क्यू\nC. द सोशल कॉन्ट्रैक्ट   |   3. व्लादिमीर इलिच लेनिन\nD. बोल्शेविक क्रांति (1917)   |   4. एडम स्मिथ","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"correct":1,"explanation":"सही सुमेलन: द स्पिरिट ऑफ द लॉज (मॉन्टेस्क्यू), वेल्थ ऑफ नेशंस (1776) (एडम स्मिथ), द सोशल कॉन्ट्रैक्ट (ज्याँ-जैक रूसो), बोल्शेविक क्रांति (1917) (व्लादिमीर इलिच लेनिन)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. द सोशल कॉन्ट्रैक्ट : व्लादिमीर इलिच लेनिन\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. द स्पिरिट ऑफ द लॉज : मॉन्टेस्क्यू\n4. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'द सोशल कॉन्ट्रैक्ट' का सही संबंध 'ज्याँ-जैक रूसो' से है (न कि 'व्लादिमीर इलिच लेनिन' से)। रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया।"},
  {"q":"'वेल्थ ऑफ नेशंस' (1776 — अहस्तक्षेप/Laissez-faire पूंजीवाद) किस अर्थशास्त्री-चिंतक की रचना है?","options":["कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","मॉन्टेस्क्यू","ज्याँ-जैक रूसो","एडम स्मिथ"],"correct":3,"explanation":"एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया। यह पुस्तक अमेरिकी स्वतंत्रता घोषणा के ही वर्ष 1776 में प्रकाशित हुई।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।) युग्म 2 सही (जर्मनी के पोलैंड ('ऑपरेशन व्हाइट') हमले के दो दिन बाद 3 सितंबर को ब्रिटेन और फ्रांस युद्ध में कूद पड़े।) युग्म 3 गलत (सही: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) — इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण)।"},
  {"q":"प्रथम विश्व युद्ध (1914-18) के बाद जर्मनी के साथ किस अपमानजनक संधि पर हस्ताक्षर हुए?","options":["कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","मॉन्टेस्क्यू","प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना","ज्याँ-जैक रूसो"],"correct":2,"explanation":"28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना। फ्रांसीसी मार्शल फॉश ने इसे 'शांति नहीं बल्कि 20 वर्षों का युद्धविराम' कहा था।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)   |   1. फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\nB. इटली का फ्लोरेंस नगर   |   2. द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\nC. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)   |   3. इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nD. बास्तील दुर्ग का पतन (14 जुलाई 1789)   |   4. यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) (इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण), इटली का फ्लोरेंस नगर (यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र), जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) (द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)), बास्तील दुर्ग का पतन (14 जुलाई 1789) (फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श))।"},
  {"q":"'इटली और जर्मनी का एकीकरण (मैजिनी, कैवूर, गैरीबाल्डी व बिस्मार्क)' के ऐतिहासिक संदर्भ में 'संधि परिणाम' निम्नलिखित में से क्या है?","options":["1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","1871 की फ्रैंकफर्ट संधि से फ्रांस को अल्सास-लॉरेन जर्मनी को देना पड़ा, जो प्रथम विश्व युद्ध का दीर्घकालिक कारण बना","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)"],"correct":1,"explanation":"इटली के एकीकरण में पीडमोंट-सार्डिनिया राज्य के राजा विक्टर इमैनुएल द्वितीय ने केंद्रीय भूमिका निभाई और 1870 में रोम के विलय के साथ एकीकरण पूरा हुआ।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बोस्टन टी पार्टी (1773)   |   1. एडम स्मिथ\nB. दास कैपिटल (1867)   |   2. सैमुअल एडम्स (अमेरिकी क्रांति)\nC. वेल्थ ऑफ नेशंस (1776)   |   3. ज्यूसेपे मैजिनी\nD. यंग इटली (1831)   |   4. कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)","options":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":2,"explanation":"सही सुमेलन: बोस्टन टी पार्टी (1773) (सैमुअल एडम्स (अमेरिकी क्रांति)), दास कैपिटल (1867) (कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)), वेल्थ ऑफ नेशंस (1776) (एडम स्मिथ), यंग इटली (1831) (ज्यूसेपे मैजिनी)।"},
  {"q":"जर्मनी के 'लौह एवं रक्त नीति' (Blood and Iron) द्वारा 1871 में जर्मन एकीकरण का वास्तुकार कौन था?","options":["प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र"],"correct":0,"explanation":"चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया। इटली के एकीकरण में कावूर, मैजिनी व गैरीबाल्डी ('लाल कुर्ती') की प्रमुख भूमिका रही।"},
  {"q":"ऐतिहासिक संदर्भ में 'इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)' (प्रमुख व्यक्तित्व व सिद्धांत) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)","इटली और जर्मनी का एकीकरण (मैजिनी, कैवूर, गैरीबाल्डी व बिस्मार्क)","फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट","यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन"],"correct":3,"explanation":"इंग्लैंड में 1688 की 'गौरवशाली क्रांति' (Glorious / Bloodless Revolution) द्वारा बिना रक्तपात संसद की सर्वोच्चता व संवैधानिक राजतंत्र स्थापित हुआ ('बिल ऑफ राइट्स 1689')।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. यंग इटली (1831) : ज्यूसेपे मैजिनी\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. बोस्टन टी पार्टी (1773) : एडम स्मिथ\n4. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'बोस्टन टी पार्टी (1773)' का सही संबंध 'सैमुअल एडम्स (अमेरिकी क्रांति)' से है (न कि 'एडम स्मिथ' से)। ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n2. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।) युग्म 2 सही (मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी।) युग्म 3 सही (1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी।)।"},
  {"q":"ऐतिहासिक संदर्भ में '14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)' (क्रांति व आदर्श) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["इटली और जर्मनी का एकीकरण (मैजिनी, कैवूर, गैरीबाल्डी व बिस्मार्क)","फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट","यूरोपीय पुनर्जागरण (Renaissance) एवं धर्मसुधार आंदोलन","औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776)"],"correct":1,"explanation":"फ्रांसीसी क्रांति के पश्चात 26 अगस्त 1789 को 'मनुष्य एवं नागरिक के अधिकारों की घोषणा' की गई, जिसका प्रभाव भारतीय संविधान की प्रस्तावना व टिपू सुल्तान तक दिखा।"},
  {"q":"इंग्लैंड में 1688 की किस क्रांति में बिना रक्तपात के राजा जेम्स द्वितीय को हटाकर संसदीय सर्वोच्चता (Bill of Rights 1689) स्थापित हुई?","options":["इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र"],"correct":0,"explanation":"1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी। दार्शनिक जॉन लॉक ने इसी संदर्भ में उदारवाद व प्राकृतिक अधिकारों का सिद्धांत दिया।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. दास कैपिटल (1867) : एडम स्मिथ\n2. वेल्थ ऑफ नेशंस (1776) : मॉन्टेस्क्यू\n3. द स्पिरिट ऑफ द लॉज : व्लादिमीर इलिच लेनिन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: दास कैपिटल (1867) — कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो))। युग्म 2 गलत (सही: वेल्थ ऑफ नेशंस (1776) — एडम स्मिथ)। युग्म 3 गलत (सही: द स्पिरिट ऑफ द लॉज — मॉन्टेस्क्यू)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लियोनार्दो दा विंची : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n2. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\n4. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)' का सही संबंध 'इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण' से है (न कि 'द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)' से)। 1688 की गौरवपूर्ण क्रांति ने ब्रिटेन में संवैधानिक राजतंत्र की पक्की नींव रखी।"},
  {"q":"फ्रांसीसी क्रांति (1789): कारण, दार्शनिक व नेपोलियन बोनापार्ट — इसके संबंध में 'क्रांति व आदर्श' कौन/क्या था?","options":["औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)","इटली एकीकरण (1861/1870): ज्यूसेपे मैजिनी ('यंग इटली' 1831 — आत्मा), काउंट कैवूर (कूटनीति — दिमाग), गैरीबाल्डी ('लाल कुर्ती' — तलवार); जर्मनी एकीकरण (1871): प्रशा के चांसलर ओटो वॉन बिस्मार्क ('रक्त और लौह नीति' — तीन युद्ध: डेनमार्क 1864, ऑस्ट्रिया सेडोवा 1866 व फ्रांस सेडान 1870 — वर्साय के शीशमहल में केसर विलियम I राज्याभिषेक)"],"correct":1,"explanation":"फ्रांसीसी क्रांति के पश्चात 26 अगस्त 1789 को 'मनुष्य एवं नागरिक के अधिकारों की घोषणा' की गई, जिसका प्रभाव भारतीय संविधान की प्रस्तावना व टिपू सुल्तान तक दिखा।"},
  {"q":"द्वितीय विश्व युद्ध में 1 सितंबर 1939 को किस देश पर जर्मन (हिटलर) आक्रमण के साथ युद्ध औपचारिक रूप से भड़का?","options":["कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार","यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)"],"correct":3,"explanation":"जर्मनी के पोलैंड ('ऑपरेशन व्हाइट') हमले के दो दिन बाद 3 सितंबर को ब्रिटेन और फ्रांस युद्ध में कूद पड़े। 2 सितंबर 1945 को जापान के आत्मसमर्पण (हिरोशिमा-नागासाकी परमाणु बम के बाद) यह युद्ध समाप्त हुआ।"},
  {"q":"'फासीवाद-नाजीवाद, द्वितीय विश्व युद्ध (1939–1945) व UNO स्थापना' के ऐतिहासिक संदर्भ में 'शीत युद्ध व गुटनिरपेक्षता' निम्नलिखित में से क्या है?","options":["1945-1991 शीत युद्ध (USA नाटो 1949 बनाम USSR वारसॉ पैक्ट 1955); चीनी क्रांति (1949 माओत्से तुंग); गुटनिरपेक्ष आंदोलन NAM (बांडुंग 1955; बेलग्रेड 1961 — नेहरू, नासिर, टीटो, सुकर्णो, नक्रूमा); सोवियत विघटन (1991, मिखाइल गोर्बाचेव 'ग्लासनोस्त-पेरेस्त्रोइका')","गुटेनबर्ग की छपाई मशीन (1450 के दशक), कोलंबस (1492 अमेरिका), मैगेलन (पृथ्वी परिक्रमा), गैलीलियो (दूरबीन)","1804 फ्रांस का सम्राट, 'नेपोलियन संहिता 1804' (कानून के समक्ष समानता), महाद्वीपीय व्यवस्था, 1815 वाटरलू युद्ध में पराजय (सेंट हेलेना निर्वासन)","विश्व का प्रथम आधुनिक लिखित संविधान (1787 फिलाडेल्फिया सम्मेलन, 1789 लागू — शक्ति पृथक्करण व अधिकार पत्र)"],"correct":0,"explanation":"शीत युद्ध के दौरान तृतीय विश्व के नव-स्वतंत्र देशों को सैन्य गुटों से दूर रखने हेतु 1961 में बेलग्रेड में प्रथम गुटनिरपेक्ष शिखर सम्मेलन (NAM) आयोजित हुआ।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बास्तील दुर्ग का पतन (14 जुलाई 1789)   |   1. मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\nB. लियोनार्दो दा विंची   |   2. द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा)\nC. इटली का फ्लोरेंस नगर   |   3. फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\nD. जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939)   |   4. यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: बास्तील दुर्ग का पतन (14 जुलाई 1789) (फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)), लियोनार्दो दा विंची (मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र), इटली का फ्लोरेंस नगर (यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र), जर्मनी का पोलैंड पर आक्रमण (1 सितंबर 1939) (द्वितीय विश्व युद्ध की तत्काल शुरुआत (ब्रिटेन-फ्रांस द्वारा जर्मनी के विरुद्ध युद्ध घोषणा))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)   |   1. प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\nB. बास्तील दुर्ग का पतन (14 जुलाई 1789)   |   2. इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nC. ओटो वॉन बिस्मार्क   |   3. कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\nD. मार्टिन लूथर (जर्मनी)   |   4. फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) (इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण), बास्तील दुर्ग का पतन (14 जुलाई 1789) (फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)), ओटो वॉन बिस्मार्क (प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)), मार्टिन लूथर (जर्मनी) (कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n2. वर्साय की संधि (1919) : प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\n3. यंग इटली (1831) : ज्यूसेपे मैजिनी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया।) युग्म 2 सही (28 जून 1919 की वर्साय संधि से जर्मनी पर भारी हर्जाना व सैन्य प्रतिबंध लगे जो WWII का बीज बना।) युग्म 3 सही (मैजिनी ने मार्से में 'यंग इटली' की स्थापना कर युवाओं में लोकतांत्रिक राष्ट्रवाद जगाया।)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n2. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र\n3. लियोनार्दो दा विंची : फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी।) युग्म 2 गलत (सही: गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) — इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण)। युग्म 3 गलत (सही: लियोनार्दो दा विंची — मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र)।"},
  {"q":"औपनिवेशिक विउपनिवेशीकरण (Decolonization): अफ्रीका, एशिया व राष्ट्रमंडल — इसके संबंध में 'प्रमुख ऐतिहासिक प्रक्रिया' कौन/क्या था?","options":["14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)","1947 भारत-पाक, 1948 श्रीलंका-बर्मा, 1949 इंडोनेशिया (सुकर्णो), 1954 डिएन बिएन फू (वियतनाम — हो ची मिन्ह, जेनेवा समझौता), 1956 स्वेज संकट (नासिर), 1957 घाना (क्वामे नक्रूमा — उप-सहारा अफ्रीका में प्रथम स्वतंत्र), 1960 'अफ्रीका का वर्ष' (17 देश स्वतंत्र), 1994 दक्षिण अफ्रीका (नेल्सन मंडेला द्वारा रंगभेद समाप्ति)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)"],"correct":1,"explanation":"दक्षिण अफ्रीका में रंगभेद (Apartheid) शासन के विरुद्ध 27 वर्ष जेल में रहने वाले नेल्सन मंडेला 1994 में दक्षिण अफ्रीका के प्रथम अश्वेत राष्ट्रपति बने।"},
  {"q":"औद्योगिक क्रांति एवं अमेरिकी स्वतंत्रता संग्राम (1776) — इसके संबंध में 'प्रमुख कारण व घटनाएँ' कौन/क्या था?","options":["इटली एकीकरण (1861/1870): ज्यूसेपे मैजिनी ('यंग इटली' 1831 — आत्मा), काउंट कैवूर (कूटनीति — दिमाग), गैरीबाल्डी ('लाल कुर्ती' — तलवार); जर्मनी एकीकरण (1871): प्रशा के चांसलर ओटो वॉन बिस्मार्क ('रक्त और लौह नीति' — तीन युद्ध: डेनमार्क 1864, ऑस्ट्रिया सेडोवा 1866 व फ्रांस सेडान 1870 — वर्साय के शीशमहल में केसर विलियम I राज्याभिषेक)","इटली (फ्लोरेंस) से उदय (14वीं-16वीं सदी); 'मानववाद का पिता' पेट्रार्क; लियोनार्डो द विंची ('मोनालिसा', 'द लास्ट सपर'); माइकल एंजेलो ('डेविड', सिस्टीन चैपल); मैकियावेली ('द प्रिंस'); कोपरनिकस (सूर्य-केंद्रित सिद्धांत); धर्मसुधार: मार्टिन लूथर (1517 जर्मनी — 95 थीसिस, प्रोटेस्टेंट आंदोलन)","औद्योगिक क्रांति (18वीं सदी मध्य ब्रिटेन से प्रारंभ — लोहा-कोयला, कृषि क्रांति व बाड़ाबंदी, जेम्स वाट भाप इंजन, स्पिनिंग जेनी हारग्रीव्स); अमेरिकी क्रांति ('प्रतिनिधित्व के बिना कर नहीं', बोस्टन टी पार्टी 16 दिसंबर 1773 — सैमुअल एडम्स, स्वतंत्रता घोषणा 4 जुलाई 1776 — थॉमस जेफरसन, जॉर्ज वाशिंगटन सेनापति, 1783 पेरिस की संधि से मान्यता)","14 जुलाई 1789 बास्तील किले का पतन (फ्रांस राष्ट्रीय दिवस); 'स्वतंत्रता, समानता व बंधुत्व' का नारा; दार्शनिक: मॉन्टेस्क्यू ('द स्पिरिट ऑफ लॉज' — शक्ति पृथक्करण), वोल्टेयर (अभिव्यक्ति-चर्च आलोचना), रूसो ('सोशल कॉन्ट्रैक्ट' — 'मनुष्य स्वतंत्र जन्मा है पर सर्वत्र जंजीरों में जकड़ा है'); जैकोबिन व रोबेस्पियरे ('आतंक का राज' 1793-94)"],"correct":2,"explanation":"सात वर्षीय युद्ध (1756-63) के बाद ब्रिटेन द्वारा उपनिवेशों पर लगाए गए स्टैम्प एक्ट (1765) व चाय कर के विरोध में ही अमेरिकी क्रांति ने गति पकड़ी।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. द सोशल कॉन्ट्रैक्ट : ज्याँ-जैक रूसो\n2. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n3. दास कैपिटल (1867) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (रूसो ने 'सामान्य इच्छा' (General Will) और जन-संप्रभुता का सिद्धांत प्रस्तुत किया।) युग्म 2 सही (एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया।) युग्म 3 सही (कार्ल मार्क्स ने वैज्ञानिक समाजवाद व वर्ग-संघर्ष के सिद्धांत का प्रतिपादन किया।)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. यंग इटली (1831) : कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो)\n2. दास कैपिटल (1867) : व्लादिमीर इलिच लेनिन\n3. बोस्टन टी पार्टी (1773) : सैमुअल एडम्स (अमेरिकी क्रांति)\n4. बोल्शेविक क्रांति (1917) : मॉन्टेस्क्यू","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: ईस्ट इंडिया कंपनी के चाय जहाजों से 342 पेटियाँ बोस्टन बंदरगाह समुद्र में फेंक दी गईं। (अन्य सही युग्म: यंग इटली (1831)→ज्यूसेपे मैजिनी, दास कैपिटल (1867)→कार्ल मार्क्स (एंगेल्स के सह-लेखन में मेनिफेस्टो), बोल्शेविक क्रांति (1917)→व्लादिमीर इलिच लेनिन)।"},
  {"q":"[PSC/CDS युग्म पहचान — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. बास्तील दुर्ग का पतन (14 जुलाई 1789) : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n2. इटली का फ्लोरेंस नगर : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\n3. ओटो वॉन बिस्मार्क : इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\n4. लियोनार्दो दा विंची : मोनालिसा, द लास्ट सपर एवं वैज्ञानिक-अभियांत्रिकी रेखाचित्र","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: इतालवी पुनर्जागरण काल के दा विंची चित्रकार, मूर्तिकार, अभियंता व शरीर विज्ञानी थे। (अन्य सही युग्म: बास्तील दुर्ग का पतन (14 जुलाई 1789)→फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श), इटली का फ्लोरेंस नगर→यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र, ओटो वॉन बिस्मार्क→प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871))।"}
]);
